select USERUNIQUE,sum(PRICE*PNUMBER) as TOTALPRICE
from ordersofuser
where MARKETNAME=#{marketName}
  and PRODUCTNAME=#{productName}
  and ENDTIME<=NEEDTIME
  and NEEDTIME>=#{begin}
  and NEEDTIME<=#{end}
  and USERUNIQUE in (select USERUNIQUE from gamegroupmember where STATUS=1 and GROUPNAME=#{groupName} )
group by USERUNIQUE


